 59	public enum ShipmentStatus {
 60	    PENDING {
 61	        @Override
 62	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
 63	            return nextStatus == SHIPPED || nextStatus == CANCELED;
 64	        }
 65	    },
 66	    SHIPPED {
 67	        @Override
 68	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
 69	            return nextStatus == IN_TRANSIT || nextStatus == RETURNED || nextStatus == CANCELED;
 70	        }
 71	    },
 72	    IN_TRANSIT {
 73	        @Override
 74	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
 75	            return nextStatus == OUT_FOR_DELIVERY || nextStatus == DELAYED || nextStatus == CANCELED
 76	                    || nextStatus == DELIVERED;
 77	        }
 78	    },
 79	    OUT_FOR_DELIVERY {
 80	        @Override
 81	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
 82	            return nextStatus == DELIVERED || nextStatus == FAILED_DELIVERY || nextStatus == CANCELED;
 83	        }
 84	    },
 85	    DELIVERED {
 86	        @Override
 87	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
 88	            return false; // 배송 완료 이후로는 상태 전환 없음
 89	        }
 90	    },
 91	    RETURNED {
 92	        @Override
 93	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
 94	            return nextStatus == CANCELED;
 95	        }
 96	    },
 97	    CANCELED {
 98	        @Override
 99	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
100	            return false; // 취소 이후 상태 전환 없음
101	        }
102	    },
103	    DELAYED {
104	        @Override
105	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
106	            return nextStatus == IN_TRANSIT || nextStatus == CANCELED;
107	        }
108	    },
109	    FAILED_DELIVERY {
110	        @Override
111	        public boolean canTransitionTo(ShipmentStatus nextStatus) {
112	            return nextStatus == RETURNED || nextStatus == OUT_FOR_DELIVERY || nextStatus == CANCELED;
113	        }
114	    };
115	
116	    public abstract boolean canTransitionTo(ShipmentStatus nextStatus);
