472	     */
473	    @Bean
474	    @StepScope
475	    public ItemProcessor<OrderShipment, OrderShipment> shipmentItemProcessor() {
476	        log.debug("배송 상태 업데이트 ItemProcessor 구성");
477	
478	        // 만약 Processor를 여러 단계로 나누고 싶다면 CompositeItemProcessorBuilder 사용도 가능
479	        return orderShipment -> {
480	            String trackingNumber = orderShipment.getTrackingNumber();
481	            Long shipmentId = orderShipment.getId();
482	
483	            if (trackingNumber == null || trackingNumber.isBlank()) {
484	                log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
485	                throw new ShipmentException(ShipmentErrorCode.TRACKING_NUMBER_INVALID);
486	            }
487	
488	            log.info("배송 상태 조회 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
489	                    shipmentId, trackingNumber, orderShipment.getStatus());
490	
491	            try {
492	                // 2-1) 현재 상태 가져오기
493	                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
494	                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}", shipmentId, currentStatus);
495	
496	                // 2-2) 매핑
497	                ShipmentStatus newStatus = mapToShipmentStatus(currentStatus);
498	                log.debug("배송 상태 매핑 결과: currentStatus={}, mappedStatus={}", currentStatus, newStatus);
499	
500	                // 현재 상태와 동일한 경우 중복 처리 방지
501	                if (orderShipment.getStatus() == newStatus) {
502	                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
503	                            shipmentId, newStatus);
504	                    return orderShipment;
505	                }
506	
507	                // 2-3) 상태에 따른 처리
508	                if (newStatus == ShipmentStatus.DELIVERED) {
509	                    log.info("배송 완료 처리: shipmentId={}, orderId={}",
510	                            shipmentId, orderShipment.getOrder().getId());
511	
512	                    orderShipment.updateStatus(ShipmentStatus.DELIVERED);
513	                    // Order 상태도 COMPLETED 로 변경
514	                    orderService.completeOrder(orderShipment.getOrder().getId());
515	                    // 알림 발송
516	                    notificationService.notifyShipmentCompleted(orderShipment.getOrder());
517	                }
518	                else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
519	                    log.info("배송 출발 처리: shipmentId={}", shipmentId);
520	                    orderShipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
521	                    // 필요시 알림, 로직 추가
522	                }
523	                else {
524	                    log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
525	                    orderShipment.updateStatus(ShipmentStatus.IN_TRANSIT);
526	                }
527	
528	                log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}", shipmentId, orderShipment.getStatus());
529	                return orderShipment; // Writer로 넘김
530	
531	            } catch (Exception e) {
532	                log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
533	                        shipmentId, trackingNumber, e.getMessage(), e);
534	
535	                // ShipmentException 타입이 아닌 경우 래핑
536	                if (!(e instanceof ShipmentException)) {
537	                    throw new ShipmentException(
538	                            ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
539	                            "배송 상태 조회 중 오류 발생: " + e.getMessage(),
540	                            e
541	                    );
542	                }
543	                throw e;
544	            }
545	        };
546	    }
