 97	            );
 98	
 99	            log.info("배송 상태 조회 완료 (문자열 응답): shipmentId={}, status={}",
100	                    shipmentId, updatedStatus);
101	
102	            // 문자열로 반환
103	            return ResponseEntity.ok(updatedStatus.name());
104	
105	        } catch (ShipmentException e) {
