108	
109	            return ResponseEntity
110	                    .status(e.getErrorCode().getStatus())
111	                    .body("Error: " + e.getMessage());
112	
113	        } catch (Exception e) {
114	            log.error("배송 상태 문자열 조회 실패 (일반 예외): shipmentId={}, error={}",
115	                    shipmentId, e.getMessage(), e);
116	
117	            return ResponseEntity.badRequest().body("Error: " + e.getMessage());
118	        }
119	    }
120	}

